settings.custom_css:
/* =========================================================
   RAMIS SHOP — PREMIUM MY ACCOUNT
   ========================================================= */

.woocommerce {
    --rp: #006660;
    --rp-dark: #004F4B;
    --rd: #003F3C;
    --rg: #FFCE3A;
    --rt: #183C3A;
    --rm: #7B8786;
    --rl: #F8FAF9;
    --rb: #E9EEEE;
    direction: rtl;
    font-family: "Yekan Bakh", sans-serif !important;
}


/* =========================
   DASHBOARD / PROFILE
========================= */

.woocommerce .wc-dashboard {
    width: 100%;
    margin: 0 0 24px !important;
    padding: 0 !important;
    overflow: hidden;
    background: #fff;
    border: 1px solid var(--rb);
    border-radius: 20px;
    box-shadow: 0 12px 38px rgba(0,102,96,.07);
}

.woocommerce .store-avatar-header {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 190px;
    padding: 30px;
    overflow: hidden;
    background:
        radial-gradient(circle at 88% 15%,rgba(255,206,58,.12),transparent 29%),
        radial-gradient(circle at 8% 85%,rgba(0,180,165,.17),transparent 34%),
        linear-gradient(135deg,var(--rd),var(--rp) 52%,#00332F);
}

.woocommerce .store-avatar-header::before,
.woocommerce .store-avatar-header::after {
    content: "";
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
}

.woocommerce .store-avatar-header::before {
    width: 300px;
    height: 300px;
    top: -190px;
    right: 8%;
    background: radial-gradient(circle,rgba(255,206,58,.16),transparent 70%);
    filter: blur(12px);
}

.woocommerce .store-avatar-header::after {
    width: 340px;
    height: 340px;
    bottom: -245px;
    left: 3%;
    background: radial-gradient(circle,rgba(0,190,175,.13),transparent 68%);
    filter: blur(18px);
}


/* =========================
   AVATAR
========================= */

.woocommerce .profile-img {
    position: relative;
    z-index: 2;
    width: 100px;
    height: 100px;
    padding: 4px;
    border-radius: 50%;
    background: linear-gradient(135deg,#fff,rgba(255,255,255,.92),rgba(255,206,58,.78));
    box-shadow: 0 14px 38px rgba(0,0,0,.25);
    box-sizing: border-box;
    transition: .4s ease;
}

.woocommerce .profile-img::before {
    content: "";
    position: absolute;
    inset: -6px;
    border: 1px solid rgba(255,206,58,.42);
    border-radius: 50%;
}

.woocommerce .profile-img img {
    width: 100%;
    height: 100%;
    display: block;
    object-fit: cover;
    border-radius: 50%;
}

.woocommerce .profile-img .loader {
    display: none !important;
}

.woocommerce .store-avatar-header:hover .profile-img {
    transform: translateY(-4px) scale(1.025);
    box-shadow: 0 18px 45px rgba(0,0,0,.29);
}


/* =========================
   USER INFO
========================= */

.woocommerce .store-avatar-footer {
    padding: 21px 25px 25px;
    text-align: center;
    background: linear-gradient(180deg,var(--rd),var(--rp-dark));
}

.woocommerce .store-name {
    margin: 0 0 6px !important;
    color: #fff !important;
    font-size: clamp(19px,2vw,23px) !important;
    font-weight: 900 !important;
    line-height: 1.65;
}

.woocommerce .store-name::after {
    content: "";
    display: block;
    width: 48px;
    height: 3px;
    margin: 8px auto 0;
    background: var(--rg);
    border-radius: 20px;
}

.woocommerce .reg-date {
    color: rgba(255,255,255,.68);
    font-size: 12px;
}

.woocommerce .store-avatar-footer .details::before {
    content: "";
    display: inline-block;
    width: 5px;
    height: 5px;
    margin-left: 7px;
    background: var(--rg);
    border-radius: 50%;
}


/* =========================
   ACCOUNT NAV
========================= */

.woocommerce .woocommerce-MyAccount-navigation {
    float: right;
    width: 250px;
    margin: 0 !important;
    padding: 0 !important;
}

.woocommerce .woocommerce-MyAccount-navigation ul {
    margin: 0 !important;
    padding: 8px !important;
    list-style: none !important;
    background: #fff;
    border: 1px solid var(--rb);
    border-radius: 18px;
    box-shadow: 0 8px 28px rgba(0,102,96,.045);
}

.woocommerce .woocommerce-MyAccount-navigation li {
    margin: 2px 0 !important;
    padding: 0 !important;
    list-style: none !important;
}

.woocommerce .woocommerce-MyAccount-navigation li a {
    display: flex !important;
    align-items: center;
    min-height: 46px;
    padding: 0 15px !important;
    color: #596866 !important;
    border-radius: 11px;
    font-size: 13px !important;
    font-weight: 600 !important;
    text-decoration: none !important;
    transition: .25s ease;
}

.woocommerce .woocommerce-MyAccount-navigation li a:hover {
    color: var(--rp) !important;
    background: rgba(0,102,96,.065);
    transform: translateX(-2px);
}

.woocommerce .woocommerce-MyAccount-navigation li.is-active > a {
    color: #fff !important;
    background: var(--rp) !important;
    box-shadow: 0 6px 16px rgba(0,102,96,.15);
}

.woocommerce .woocommerce-MyAccount-navigation li a i {
    width: 28px;
    margin-left: 8px;
    color: currentColor;
    text-align: center;
}


/* =========================
   ACCOUNT CONTENT
========================= */

.woocommerce .woocommerce-MyAccount-content {
    float: left;
    width: calc(100% - 275px);
    margin: 0 !important;
    padding: 28px !important;
    background: #fff;
    border: 1px solid var(--rb);
    border-radius: 20px;
    box-sizing: border-box;
}

.woocommerce .woocommerce-MyAccount-content > p {
    line-height: 2;
}

.woocommerce .woocommerce-MyAccount-content > p:first-of-type {
    margin: 0 0 12px !important;
    color: #5F6D6B;
    font-size: 14px;
}

.woocommerce .woocommerce-MyAccount-content > p:first-of-type strong {
    color: var(--rt);
}

.woocommerce .woocommerce-MyAccount-content > p a {
    color: var(--rp) !important;
    font-weight: 700;
    text-decoration: none !important;
}

.woocommerce .woocommerce-MyAccount-content > p:nth-of-type(2) {
    margin: 0 0 25px !important;
    padding: 15px 17px;
    color: #687573;
    background: var(--rl);
    border: 1px solid #EDF2F1;
    border-radius: 12px;
    font-size: 13px;
}


/* =========================
   PROFILE CARD
========================= */

.pooshe-profile-content {
    width: 100%;
    margin: 0 !important;
    padding: 22px !important;
    background: #fff;
    border: 1px solid var(--rb);
    border-radius: 17px;
    box-sizing: border-box;
}

.pooshe-profile-content table {
    width: 100%;
    margin: 0 !important;
    border-collapse: separate !important;
    border-spacing: 10px !important;
    table-layout: fixed;
}

.pooshe-profile-content td {
    width: 50%;
    padding: 18px 20px !important;
    background: var(--rl);
    border: 1px solid #EDF2F1 !important;
    border-radius: 13px;
    transition: .25s ease;
}

.pooshe-profile-content td:hover {
    background: #fff;
    border-color: rgba(0,102,96,.18) !important;
    box-shadow: 0 7px 20px rgba(0,102,96,.07);
    transform: translateY(-2px);
}

.pooshe-profile-content .title {
    position: relative;
    margin-bottom: 6px;
    padding-right: 12px;
    color: var(--rm);
    font-size: 12px;
}

.pooshe-profile-content .title::before {
    content: "";
    position: absolute;
    right: 0;
    top: 50%;
    width: 3px;
    height: 15px;
    background: var(--rp);
    border-radius: 10px;
    transform: translateY(-50%);
}

.pooshe-profile-content .value {
    color: var(--rt);
    font-size: 14px;
    font-weight: 700;
    line-height: 1.8;
    word-break: break-word;
}


/* =========================
   EDIT BUTTON
========================= */

.pooshe-profile-content .pooshe-edit-profile-btn {
    display: inline-flex !important;
    align-items: center;
    justify-content: center;
    gap: 8px;
    min-height: 43px;
    margin-top: 14px;
    padding: 0 20px !important;
    color: #fff !important;
    background: var(--rp) !important;
    border: 1px solid var(--rp) !important;
    border-radius: 10px;
    font-size: 12px !important;
    font-weight: 700 !important;
    text-decoration: none !important;
    box-shadow: 0 6px 16px rgba(0,102,96,.13);
    transition: .25s ease;
}

.pooshe-profile-content .pooshe-edit-profile-btn:hover {
    background: var(--rp-dark) !important;
    border-color: var(--rp-dark) !important;
    transform: translateY(-2px);
}


/* =========================
   TABLET
========================= */

@media (max-width:1024px) {
    .woocommerce .woocommerce-MyAccount-navigation {
        width: 215px;
    }

    .woocommerce .woocommerce-MyAccount-content {
        width: calc(100% - 235px);
        padding: 22px !important;
    }

    .woocommerce .profile-img {
        width: 88px;
        height: 88px;
    }
}


/* =========================
   MOBILE
========================= */

@media (max-width:767px) {

    .woocommerce .woocommerce-MyAccount-navigation,
    .woocommerce .woocommerce-MyAccount-content {
        float: none !important;
        width: 100% !important;
    }

    .woocommerce .wc-dashboard {
        border-radius: 16px;
    }

    .woocommerce .store-avatar-header {
        min-height: 140px;
        padding: 22px 18px;
    }

    .woocommerce .profile-img {
        width: 76px;
        height: 76px;
        padding: 3px;
    }

    .woocommerce .store-avatar-footer {
        padding: 16px 17px 19px;
    }

    .woocommerce .store-name {
        font-size: 18px !important;
    }

    .woocommerce .woocommerce-MyAccount-navigation {
        margin-bottom: 15px !important;
    }

    .woocommerce .woocommerce-MyAccount-navigation ul {
        padding: 7px !important;
        border-radius: 15px;
    }

    .woocommerce .woocommerce-MyAccount-navigation li.responsive-toggle {
        display: block !important;
    }

    .woocommerce .woocommerce-MyAccount-navigation li a {
        min-height: 42px;
        padding: 0 13px !important;
        font-size: 12px !important;
    }

    .woocommerce .woocommerce-MyAccount-content {
        padding: 17px !important;
        border-radius: 16px;
    }

    .pooshe-profile-content {
        padding: 12px !important;
    }

    .pooshe-profile-content table {
        border-spacing: 0 !important;
    }

    .pooshe-profile-content tr {
        display: flex;
        flex-direction: column;
        gap: 8px;
        margin-bottom: 8px !important;
    }

    .pooshe-profile-content td {
        width: 100% !important;
        padding: 14px 15px !important;
    }

    .pooshe-profile-content .pooshe-edit-profile-btn {
        width: 100%;
    }
}


/* =========================
   SMALL MOBILE
========================= */

@media (max-width:480px) {
    .woocommerce .woocommerce-MyAccount-content {
        padding: 13px !important;
    }

    .woocommerce .store-avatar-header {
        min-height: 125px;
        padding: 20px 15px;
    }

    .woocommerce .profile-img {
        width: 68px;
        height: 68px;
    }

    .woocommerce .store-name {
        font-size: 16px !important;
    }

    .pooshe-profile-content {
        padding: 10px !important;
    }

    .pooshe-profile-content td {
        padding: 13px !important;
    }
}



/*********************/
